#!/usr/bin/env python3
from pathlib import Path
import re, sys

ROOT = Path(__file__).resolve().parents[1]
P = ROOT / 'homeopathy-encyclopedia'
I = P / 'includes'
D = ROOT / 'docs'
T = ROOT / 'tests'
ROUND = int(sys.argv[1]) if len(sys.argv) > 1 else 0
if ROUND not in range(1, 21):
    raise SystemExit('round must be 1..20')

def rd(path): return Path(path).read_text(encoding='utf-8')
def wr(path, text): Path(path).write_text(text, encoding='utf-8')
def replace_once(path, old, new, label):
    path=Path(path); s=rd(path); n=s.count(old)
    if n != 1: raise SystemExit(f'{label}: expected one match, found {n} in {path}')
    wr(path, s.replace(old,new,1))
def replace_between(path, start, end, new, label):
    path=Path(path); s=rd(path); a=s.find(start)
    if a<0: raise SystemExit(f'{label}: start marker missing')
    b=s.find(end,a+len(start))
    if b<0: raise SystemExit(f'{label}: end marker missing')
    wr(path,s[:a]+new+s[b:])
def append_review(n, text, status='DEFECT'):
    path=D/'FILE-06-v2.4.17-EIGHTEENTH-TWENTY-ROUND-REVIEW.md'
    if not path.exists():
        wr(path,'# File 06 v2.4.17 — Eighteenth Fresh Twenty-Round Review\n\nRepository-only corrective record. Staging/live/operational status is not established by this review.\n\n')
    s=rd(path)
    if re.search(rf'^{n}\. \*\*',s,re.M): return
    with path.open('a',encoding='utf-8') as f: f.write(f'{n}. **{status}** — {text}\n')

